window.RP_SESSION={"id":"S-9f2cee8de538","messages":[{"id":"RP-III-0108364","time":"2026-05-26T22:47:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108365","time":"2026-05-26T22:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[9] + [1] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0108366","time":"2026-05-26T22:47:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"도서관에서 책을 읽고 있는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108367","time":"2026-05-26T22:47:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108368","time":"2026-05-26T22:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 8 = 8\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0108369","time":"2026-05-26T22:47:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"읽고 있는 책은 저번에 조니와 함께 읽었던 요리책.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108370","time":"2026-05-26T22:49:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마침 지금 있는 재료로 만들 수 있는 레시피가 있다!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108371","time":"2026-05-26T22:54:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"레마?\"\n레마 발견하고는 다가간다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108372","time":"2026-05-26T22:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"일단 물로 씻지 않고 젖은 면포로 먼지만 털어낸 난장이버섯, 그물버섯, 큰갓버섯을 적절한 크기로 썰고, 데쳐서 독을 뺀 곰보버섯도 반으로 자른다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108373","time":"2026-05-26T22:57:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 멜리아! 조, 조금만 기다려. 맛있는 버섯 요리를 마, 만들어 줄게! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108374","time":"2026-05-26T22:58:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"버섯 좋지! 헤헤, 기대할게!\"\n헤실 거리며 요리하는 모습 옆에서 구경한다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108375","time":"2026-05-26T23:01:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 점심에 먹고 남은 송어 필렛 한 덩어리, 소금에 잠시 절여둔 그것을 다시 꺼내 소금을 털어내고 살을 먹기 좋은 크기로 자른다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108376","time":"2026-05-26T23:04:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"리크는 씻은 뒤 채로 썰어서 물기를 털어내고 대나무 채반에 받쳐 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108377","time":"2026-05-26T23:07:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 멜리아. 여기 기, 길드 어떤 것 같아? \"\n\n버섯과 리크에는 소금간을 한 뒤 팬에 기름을 둘러 예열하고 잠시 멜리아에게 말을 걸며 시간을 떼운다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108378","time":"2026-05-26T23:11:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"응? 좋은 것 같아! 사람들도 다 친절하고! 헤헤...\"\n헤실헤실 웃으며 즐거운 듯한 말투로 얘기한다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108379","time":"2026-05-26T23:15:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 역시, 나를 따, 따라오길 잘했지! \"\n\n재료에서 수분이 빠지는 동안 멜리아 옆에 앉아서 도란도란 수다를 떤다.\n\n\" 지내다 보, 보니까 할 일도 마, 많고 좋은 사람들도 많은 거, 것 같아. 여기 있으면 내가 더 조, 좋은 방향으로 가고 있는 것 가, 같은 느낌이 들어. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108380","time":"2026-05-26T23:16:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"맞아! 나도 여기 오고 너무 즐겁게 지내고 있어! 너도 많이 좋아지고 행복해진 것 같아서 너무 다행이다!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108381","time":"2026-05-26T23:21:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 헤헤, 멜리아도 나중에 가, 같이 의뢰도 나가고 하자! \"\n\n레마는 적절히 수분이 빠지고 간이 밴 재료들을 밀가루를 묻히고, 계란물을 찍어서 충분히 예열된 팬에 부치기 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108382","time":"2026-05-26T23:21:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고소한 버섯, 생선, 그리고 마치 우리네 부추전 비슷한 비쥬얼로 부쳐지는 리크 전의 향기들이 올라온다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108383","time":"2026-05-26T23:26:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"좋아!\"\n옆에서 팬에 재료들 부치는 거 구경한다.\n\"역시 레마야, 요리 진짜 잘한다!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108384","time":"2026-05-26T23:27:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"전들을 완성해서 따로 뺀 뒤, 남은 밀가루와 계란물에 물을 조금 더 붓고 팬에 그대로 얇게 부어 익힌다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108385","time":"2026-05-26T23:28:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그렇게 몇 번을 반복하자 기름, 밀가루, 계란 모두 조금의 낭비도 없이 배를 채울 수 있는 팬케이크로 만들어진다!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108386","time":"2026-05-26T23:28:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 자, 머, 먹어보자! \"\n\n버섯 전 하나를 포크로 찍어 멜리아의 입에 넣어 준다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108387","time":"2026-05-26T23:32:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"음...! 너무 맛있다!\"\n한입 먹고는 너한테 엄지척 날린다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108388","time":"2026-05-26T23:34:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 좋아. 와, 완전 뿌듯해! \"\n\n고소하고 파스슥 부서지는 반죽 안에 향긋하고 쫀득한 버섯, 살이 단단하고 맛있는 생선, 살짝 매콤하고 달큰한 리크까지.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108389","time":"2026-05-26T23:34:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이거...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108390","time":"2026-05-26T23:34:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"맥주를 못 참겠다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108391","time":"2026-05-26T23:34:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 짠! \"\n\n레마는 맥주를 가져와서 멜리아와 짠을 한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108392","time":"2026-05-26T23:36:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"짠!\"\n짠하고는 원샷 해버린다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108393","time":"2026-05-26T23:38:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어흐, 조, 좋다! \"\n\n레마는 기분 좋게 맥주로 또 입을 씻어내리고, 부친 생선도 한 점 집어 먹고... 간만에 친구끼리 모여 맛있게 밥과 술을 즐기고 있다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108394","time":"2026-05-26T23:42:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"같이 먹고 있는 팬케이크는 사실 버터도 없이 그냥 기름에 밀가루, 계란, 소금만 들어간 것이지만. 중세에 이 정도 맛이면 평민들에게는 사실 농사가 잘 되어야 일상에서 먹을 수 있는 메뉴겠지...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108395","time":"2026-05-26T23:49:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"레마는 지금 좋아하는 사람 있어?\"\n살짝 취한 듯하다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108396","time":"2026-05-26T23:49:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어, 어? 그, 그건... 그거언... \"\n\n취한 김에 할 수 있는 토크,","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108397","time":"2026-05-26T23:49:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그... 그게... \"\n\n있기는 한 모양인데.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108398","time":"2026-05-26T23:50:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"응? 비밀로 해줄게!\"\n눈 반짝반짝","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108399","time":"2026-05-26T23:51:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ■■ 씨도 정말 채, 챙겨 주고 싶고, 곁에 두고 있고 시, 싶은 마음이 들고... ■■ 씨는 그냥 가, 같이 있으면 재밌어서 좋고... \"\n\n좋아하다의 뜻을 잘못 알아들은 것 같다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108400","time":"2026-05-26T23:51:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ■■ 씨는 그냥 보고 이, 있으면 든든하달까? 그리고 ■■ 씨도... \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108401","time":"2026-05-26T23:51:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"응? 아니아니! 이성적으로 좋아하는 사람!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108402","time":"2026-05-26T23:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n일부러 회피했지만 정곡을 찔렸다. 머리에서 김이 나고 얼굴이 빨개지는 것 같아 보이는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108403","time":"2026-05-26T23:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108404","time":"2026-05-26T23:54:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[6] + [1] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0108405","time":"2026-05-26T23:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108406","time":"2026-05-26T23:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"탈출할 방법이 안 떠올라!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108407","time":"2026-05-26T23:58:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그, 그거언... \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108408","time":"2026-05-26T23:59:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"멜리아에게만 속삭이며 어떤 이름을 말한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108409","time":"2026-05-27T00:00:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"정말? 난 레마를 응원해! 잘 되길 빌게!\"\n방긋 웃는다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0108410","time":"2026-05-27T00:17:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-III-0108411","time":"2026-05-27T00:17:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
